from PIL import Image
import numpy as np
try: import cv2
except Exception as e:print(e);raise
for cam in ['top','oblique','side','front']:
 im=np.array(Image.open('/app/output/initial/last/'+cam+'.jpg').convert('RGB'))
 D=np.load('/app/output/initial/depth_'+cam+'.npy')[0].astype(float)
 gray=im.mean(2); mask=((gray<155)&(D<1.5)&(D>0.75)).astype('uint8')
 if cam=='top': roi=(100,50,220,140)
 elif cam=='oblique':roi=(50,60,210,165)
 elif cam=='side':roi=(30,60,245,180)
 else:roi=(70,55,250,165)
 x1,y1,x2,y2=roi; sub=mask[y1:y2,x1:x2]
 n,l,stats,cents=cv2.connectedComponentsWithStats(sub,8)
 print('\n',cam,'components')
 for x,y,w,h,a in sorted(stats[1:],key=lambda x:-x[4])[:20]:
  if a>=3: 
   X=x+x1;Y=y+y1;vals=D[Y:Y+h,X:X+w];pix=im[Y:Y+h,X:X+w]
   print((X,Y,w,h,a),'center',cents[list(stats[:,4]).index(a)] if False else '', 'depth median',np.median(vals), 'rgb',np.median(pix.reshape(-1,3),axis=0))
