import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=['front','side','oblique'],include_depth=True,video='both')
ps={'front':[(153,132),(150,135),(160,135),(140,132)],'side':[(140,130),(138,132),(145,130),(150,130)],'oblique':[(145,133),(150,135),(160,135),(130,132)]}
for c,coords in ps.items():
 K=np.array(o.meta['cameras'][c]['intrinsic_cv']);M=np.array(o.meta['cameras'][c]['cam2world_gl']);D=o.depth[c][0]
 for u,v in coords:
  z=float(D[v,u]);p=M@np.array([(u-160)*z/K[0,0],-(v-120)*z/K[1,1],-z,1]);print(c,(u,v),round(z,3),np.round(p[:3],3))
